          "rubric": "Menjelaskan massa sebagai ukuran kelembaman intrinsik bernilai skalar konstan di mana pun, sedangkan berat adalah gaya tarik gravitasi vektor yang bergantung percepatan g lokal.",
          "modelAnswer": "Massa inersia adalah besaran skalar intrinsik yang mengukur resistensi atau kelembaman suatu benda terhadap percepatan saat dikenai gaya (m = F/a); nilainya selalu konstan di seluruh penjuru alam semesta dan diukur dalam satuan kilogram (kg) menggunakan neraca analitis (neraca sama lengan). Sebaliknya, gaya berat (W = m*g) adalah besaran vektor berupa gaya tarik gravitasi bumi yang dialami oleh massa tersebut. Nilai gaya berat bervariasi bergantung pada intensitas medan percepatan gravitasi lokal (misalnya di kutub bumi lebih besar dibanding di khatulistiwa, dan di bulan hanya 1/6 berat di bumi). Berat diukur dalam satuan Newton (N) menggunakan dinamometer (neraca pegas).",
