          "rubric": "Menguraikan dekomposisi gaya sumbu X sejajar bidang miring (mg sin theta) dan sumbu Y tegak lurus (N - mg cos theta = 0), memasukkan kondisi batas fs_max = mu_s * N, hingga diperoleh rumus tan theta_c = mu_s.",
          "modelAnswer": "Langkah penurunan analitis: (1) Pilih sistem koordinat Kartesius miring: sumbu X sejajar permukaan bidang miring ke bawah, sumbu Y tegak lurus bidang miring ke atas. (2) Uraikan gaya-gaya pada balok: Gaya normal N pada sumbu Y positif; Komponen gaya gravitasi sumbu Y: Wy = - m * g * cos theta; Komponen gaya gravitasi sumbu X: Wx = + m * g * sin theta; Gaya gesek statis fs mengarah ke atas bidang miring (-X). (3) Keseimbangan pada sumbu Y: Sigma Fy = 0 => N - m * g * cos theta = 0 => N = m * g * cos theta. (4) Kondisi tepat akan meluncur (kritis) tercapai saat Wx tepat mengimbangi gaya gesek statis maksimum (fs_max = mu_s * N): Sigma Fx = 0 => m * g * sin theta_c - fs_max = 0 => m * g * sin theta_c = mu_s * (m * g * cos theta_c). (5) Bagi kedua ruas dengan m * g * cos theta_c: (sin theta_c) / (cos theta_c) = mu_s => tan(theta_c) = mu_s. Jadi sudut kritis tercapai saat theta_c = arctan(mu_s).",
