          "rubric": "Menjelaskan fungsi kemiringan agar komponen gaya normal menyediakan gaya sentripetal yang dibutuhkan, menguraikan N sin theta = m v^2 / R dan N cos theta = m g, menghasilkan rumus v = sqrt(R g tan theta).",
          "modelAnswer": "Tikungan jalan tol atau trek balap dibuat miring bersudut theta untuk meningkatkan keselamatan kendaraan saat melaju pada kelajuan tinggi tanpa harus bergantung pada gaya gesek ban (yang bisa hilang drastis saat hujan licin atau jalan beres atau bersalju). Dengan memiringkan jalan, komponen horizontal gaya kontak normal dari permukaan jalan (N * sin theta) secara langsung bertindak sebagai penyedia gaya sentripetal ke arah pusat putaran. Penurunan rumus: Pada sumbu vertikal (keseimbangan): Sigma Fy = 0 => N * cos theta = m * g => N = (m * g) / cos theta. Pada sumbu horizontal (dinamika melingkar): Sigma Fx = F_sentripetal => N * sin theta = m * (v^2 / R). Substitusikan nilai N: ((m * g) / cos theta) * sin theta = m * (v^2 / R) => g * tan theta = v^2 / R => v = sqrt(R * g * tan theta). Kecepatan ini disebut kelajuan desain (design speed) di mana mobil dapat berbelok mulus meski tanpa gesekan sama sekali.",
          "reference": "Modul 03 Fisika, Bab 5 Hal. 17-20"
