          "modelAnswer": "Ditinjau dari prinsip termodinamika kimia: (1) Reaksi Eksoterm: Terjadi pelepasan kalor dari sistem kimia ke lingkungan. Karena sistem kehilangan energi termal, entalpi produk lebih kecil daripada entalpi pereaksi (H_produk < H_reaktan), sehingga nilai perubahan entalpi bertanda negatif (Delta H < 0). Lingkungan mengalami kenaikan temperatur. Pada kurva profil energi, garis reaktan berada di level atas, mendaki puncak kompleks teraktivasi (Ea), lalu turun curam ke garis produk di level bawah. (2) Reaksi Endoterm: Terjadi penyerapan kalor dari lingkungan ke dalam sistem kimia. Akibatnya, entalpi produk lebih besar dari entalpi pereaksi (H_produk > H_reaktan), sehingga Delta H bernilai positif (Delta H > 0). Suhu lingkungan mengalami penurunan (wadah terasa dingin). Pada kurva profil energi, garis reaktan berada di level bawah, mendaki puncak penghalang energi aktivasi tinggi, dan berakhir pada garis produk di level yang lebih tinggi.",
