          "rubric": "Menentukan titik koordinat y1 = f(2), menghitung gradien garis singgung m1 = f'(2), menyusun rumus garis singgung y - y1 = m1(x - x1), menentukan gradien normal m2 = -1/m1, dan menyusun persamaan garis normal.",
          "modelAnswer": "Langkah-langkah analitis: (1) Tentukan koordinat titik singgung (x1, y1): Untuk x1 = 2 => y1 = 2(2^2) - 5(2) + 3 = 2(4) - 10 + 3 = 8 - 10 + 3 = 1. Jadi titik singgung adalah P(2, 1). (2) Tentukan gradien garis singgung (m1): Turunan kurva y' = 4x - 5. Untuk x = 2 => m1 = 4(2) - 5 = 8 - 5 = 3. (3) Persamaan garis singgung: y - y1 = m1 (x - x1) => y - 1 = 3 (x - 2) => y - 1 = 3x - 6 => y = 3x - 5 (atau 3x - y - 5 = 0). (4) Tentukan gradien garis normal (m2): Garis normal tegak lurus garis singgung, sehingga m1 * m2 = -1 => m2 = -1 / 3. (5) Persamaan garis normal: y - 1 = -1/3 (x - 2) => kalikan 3: 3y - 3 = - (x - 2) => 3y - 3 = -x + 2 => x + 3y - 5 = 0.",
