          "question": "Sebuah kawat sepanjang 120 cm akan dibuat menjadi kerangka persegi panjang. Tentukan ukuran panjang dan lebar persegi panjang tersebut agar luas daerah yang dilingkupinya mencapai nilai maksimum!",
          "rubric": "Menyusun fungsi kendala keliling 2(p + l) = 120, menyatakan luas L sebagai fungsi satu variabel L(p) = p(60 - p), mencari turunan L'(p) = 0, menguji turunan kedua L''(p) < 0, dan menyimpulkan p = 30 cm dan l = 30 cm.",
          "modelAnswer": "Penyelesaian masalah optimasi diferensial: (1) Definisikan variabel: Misalkan panjang persegi panjang adalah p dan lebar adalah l. (2) Fungsi kendala: Kawat membentuk keliling, sehingga 2p + 2l = 120 => p + l = 60 => l = 60 - p. Karena panjang dan lebar harus positif, maka 0 < p < 60. (3) Fungsi tujuan (luas yang dimaksimalkan): Luas L = p * l = p * (60 - p) = 60p - p^2. (4) Kondisi stasioner untuk ekstremum: L'(p) = dL/dp = 60 - 2p = 0 => 2p = 60 => p = 30 cm. (5) Uji kecekungan (turunan kedua): L''(p) = -2. Karena L''(30) = -2 < 0, kurva cekung ke bawah dan p = 30 menghasilkan luas maksimum mutlak. (6) Hitung lebar dan luas maksimum: Lebar l = 60 - 30 = 30 cm. Luas maksimum adalah L_maks = 30 * 30 = 900 cm^2 (tercapai saat bentuknya berupa persegi).",
