          "id": "m6_es_5",
          "question": "Bagaimanakah strategi memelihara integrasi nasional dan kohesi sosial di tengah ancaman politik identitas dan etnosentrisme di Indonesia?",
          "rubric": "Menjelaskan penguatan wawasan kebangsaan Bhinneka Tunggal Ika, pendidikan multikulturalisme, penegakan hukum anti-diskriminasi, serta pemerataan pembangunan ekonomi antar-wilayah.",
          "modelAnswer": "Strategi komprehensif memelihara integrasi nasional dan kohesi sosial: (1) Penguatan Nilai Konsensus Nasional: Memperkokoh pemahaman empat pilar kebangsaan (Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika) sebagai payung integrasi normatif yang mengikat seluruh keragaman etnis dan agama di atas kesetaraan hak kewarganegaraan. (2) Penerapan Pendidikan Berbasis Multikulturalisme: Mengintegrasikan kurikulum literasi kritis di sekolah yang menanamkan sikap empati kultural, toleransi terhadap perbedaan pandangan, dan melatih siswa membongkar stereotipe serta prasangka etnosentrisme sejak usia dini. (3) Penegakan Hukum yang Adil dan Tegas: Melarang dan menindak segala bentuk ujaran kebencian, diskriminasi SARA, dan instrumentalisasi politik identitas yang mengeksploitasi sentimen primordial demi kekuasaan pragmatis. (4) Keadilan Sosial dan Pemerataan Pembangunan: Memperkuat integrasi fungsional melalui distribusi ekonomi yang adil antardaerah (khususnya wilayah 3T), mempercepat pembangunan infrastruktur antarpulau, dan membuka akses modal usaha mikro agar tidak tercipta kesenjangan struktural antara pusat dan daerah.",
